{{ snippet("header") }}

    <p>{{ __("hello_name", {"[name]": customer_name}) }},</p>
    <p>{{ __("quotation_approved_message") }}</p>

    <table style="width:100%; border-collapse: collapse; margin-top: 15px;">
        <tr>
            <th style="text-align:left; border-bottom:1px solid #ccc; padding:8px;">{{ __("product_name") }}</th>
            <th style="text-align:left; border-bottom:1px solid #ccc; padding:8px;">{{ __("quantity") }}</th>
            <th style="text-align:left; border-bottom:1px solid #ccc; padding:8px;">{{ __("price") }}</th>
        </tr>
        {% for  row in products %}
            <tr style="font-size: 14px; font-family: Helvetica, Arial, sans-serif; font-weight: normal; text-transform: uppercase; text-align: center; vertical-aling: middle;">
                {% for  column in row %}
                    <td style="padding:10px 0px; border-bottom: 1px solid #ebebeb; font-family: Helvetica, Arial, sans-serif;">{{ column }}</td>
                {% endfor %}
            </tr>
        {% endfor %}
        {% if quotation_total %}
                <tr style="font-size: 14px; font-family: Helvetica, Arial, sans-serif; font-weight: normal; text-transform: uppercase; text-align: center; vertical-aling: middle;">
                    <td style="padding:10px 0px; border-bottom: 1px solid #ebebeb; font-family: Helvetica, Arial, sans-serif;">{% if quotation_discount %}{{__('subtotal')}} {% else %} {{__('total')}} {% endif %}</td>
                        <td style="padding:10px 0px; border-bottom: 1px solid #ebebeb; font-family: Helvetica, Arial, sans-serif;"></td>
                        <td style="padding:10px 0px; border-bottom: 1px solid #ebebeb; font-family: Helvetica, Arial, sans-serif;">{{ quotation_total }}</td>
                </tr>
        {% endif %}
        {% if quotation_discount %}
                    <tr style="font-size: 14px; font-family: Helvetica, Arial, sans-serif; font-weight: normal; text-transform: uppercase; text-align: center; vertical-aling: middle;">
                    <td style="padding:10px 0px; border-bottom: 1px solid #ebebeb; font-family: Helvetica, Arial, sans-serif;">Discounted Price</td>
                        <td style="padding:10px 0px; border-bottom: 1px solid #ebebeb; font-family: Helvetica, Arial, sans-serif;"></td>
                        <td style="padding:10px 0px; border-bottom: 1px solid #ebebeb; font-family: Helvetica, Arial, sans-serif;">{{ quotation_discount }}</td>
                </tr>
        {% endif %}

    </table>

    <p>{{ __("quotation_approved_next_steps") }}</p><a href="{{ placeorderhref }}" target="_blank">{{__("proceed_to_payment")}}</a>

    {{ snippet("footer") }}

